mapper.update:
UPDATE requirement
title = #{title}, detail = #{detail}, category_id = #{categoryId}, budget_min = #{budgetMin}, budget_max = #{budgetMax}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT r.*, up.nickname AS publisher_name
FROM requirement r LEFT JOIN user_profile up ON r.publisher_id = up.account_id
WHERE r.id = #{id}

SELECT r.*, up.nickname AS publisher_name
FROM requirement r LEFT JOIN user_profile up ON r.publisher_id = up.account_id
WHERE r.publisher_id = #{publisherId}
ORDER BY r.create_time DESC
LIMIT #{offset}, #{limit}

SELECT r.*, up.nickname AS publisher_name
FROM requirement r LEFT JOIN user_profile up ON r.publisher_id = up.account_id
WHERE r.audit_status = 'APPROVED' AND r.visibility_status = 'PUBLIC'
AND r.category_id = #{categoryId}
AND r.budget_max >= #{budgetMin}
AND r.budget_min <= #{budgetMax}

    AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.detail LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY r.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM requirement
WHERE audit_status = 'APPROVED' AND visibility_status = 'PUBLIC'
AND category_id = #{categoryId}
AND budget_max >= #{budgetMin}
AND budget_min <= #{budgetMax}

    AND (title LIKE CONCAT('%', #{keyword}, '%') OR detail LIKE CONCAT('%', #{keyword}, '%'))

SELECT r.*, up.nickname AS publisher_name
FROM requirement r LEFT JOIN user_profile up ON r.publisher_id = up.account_id

    r.audit_status = #{auditStatus}

ORDER BY r.create_time DESC
LIMIT #{offset}, #{limit}
